import Foundation
import AdswizzSDKCore

protocol AppAnalyticsConnectorDelegate: AnyObject {
    func appAnalyticsConnector(_ connector: AppAnalyticsConnector, didLog event: AnalyticsEvent, with description: String)
}

// This is an example of how to implement the `AnalyticsConnector` protocol for a custom analytics connector in your application.
// The `log` method simply prints every event generated by AdswizzSDK and sent to its connectors.
class AppAnalyticsConnector: AnalyticsConnector {
    weak var delegate: AppAnalyticsConnectorDelegate?
    var shouldLog: Bool = false {
        didSet {
            if shouldLog {
                firstTime = false
                tempEvents.forEach {
                    log($0)
                }
            }
        }
    }
    private var tempEvents: [AnalyticsEvent] = []
    private var firstTime = true
    
    func log(_ event: AnalyticsEvent, _ timestamp: Date) {
        DispatchQueue.main.async {
            self.log(event)
        }
    }
    
    func send(forced: Bool) {
    }
    
    private func log(_ event: AnalyticsEvent) {
        if !shouldLog && firstTime {
            tempEvents.append(event)
            return
        }
        delegate?.appAnalyticsConnector(self, didLog: event, with: event.description)
    }
}

extension AnalyticsEvent {
    var description: String {
        var result = ""
        result += "[Analytics] id: \(id)\n"
        result += "[Analytics] category: \(category)\n"
        result += "[Analytics] level: \(level)\n"
        if let params = params {
            result += "[Analytics] params: \(params)\n"
        }
        if let customParams = customParams {
            result += "[Analytics] custom params: \(customParams)"
        }
        return result
    }
}

extension AASDKAnalytics.Level: CustomStringConvertible {
    public var description: String {
        switch self {
        case .none: return "none"
        case .error: return "error"
        case .info: return "info"
        @unknown default: return "unknown"
        }
    }
}
